import{z as B,x as d,o as r,c as p,q as E,j as s,D as e,d as t,s as i,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"有限状态机","description":"","frontmatter":{"title":"有限状态机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fsm-control.md","filePath":"cs/fsm-control.md","lastUpdated":1791413859000}'),A={name:"cs/fsm-control.md"};function m(c,a,h,F,S,f){const l=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=E('<h1 id="有限状态机" tabindex="-1">有限状态机 <a class="header-anchor" href="#有限状态机" aria-label="Permalink to &quot;有限状态机&quot;">​</a></h1><div class="epigraph"><p>现态存在寄存器里，下一态与输出都是现态和输入的组合函数；控制器先画成这样一份图。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/register-shift">寄存器与移位</a>钉死了 \\(n\\) 位使能寄存器。本课不重讲桶形移位，也不从自动机理论的正则语言另起。缺口是：寄存器可以存任何比特，还没有约定这些比特表示<strong>控制步骤</strong>。后课多周期 CPU、总线协议、外设，都要把步骤画成有限状态机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合网瞬时，时序需要「现在处于哪一步」。缺口是 FSM：有限状态集 \\(S\\)，输入字母、输出字母，转移 \\(\\delta:S\\times\\Sigma\\to S\\)，输出 \\(\\lambda\\) 或 Moore 的 \\(\\lambda:S\\to\\) 输出。现态用 \\([\\log_2|S|]\\) 位寄存器（或独热）。下一态逻辑与输出逻辑是组合，必须满足建立保持。</p><p><span class="marginnote">数字实例：要装 8 个状态，二进制编码只需 \\(\\lceil\\log_2 8\\rceil = 3\\) 个触发器；独热编码要 8 个（任一时刻只有一位为 1）。省下 5 个 FF 的代价是译码组合逻辑变多变深。</span></p><p><span class="marginnote">Moore 与 Mealy 一句话分清：Moore 的输出只由「现在在哪个状态」决定，Mealy 的输出还偷看一眼输入。所以 Mealy 能当拍响应输入，Moore 总要等状态切换才改输出。</span></p><p>Mealy 输出依赖输入，路径更短或更长取决于是否把输入算进关键路径；Moore 输出只看状态，往往更稳、多一拍。本课两种都承认，后课控制器常用混合。</p><h3 id="状态图不是程序流程图" tabindex="-1">状态图不是程序流程图 <a class="header-anchor" href="#状态图不是程序流程图" aria-label="Permalink to &quot;状态图不是程序流程图&quot;">​</a></h3><p>边是时钟拍上的转移，不是「函数调用」。无时钟的异步状态机不在主干。把 FSM 画成可以停留在组合环里等握手而无状态寄存器，会绕过上一课的 FF。</p><p><span class="marginnote">Harris 用交通灯、序列检测当例子。后课多周期取指/译码/执行是同一套：每个圆圈一拍。本课不引入微程序 ROM，那是更后一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列状态、编码、画 \\(\\delta\\) 与 \\(\\lambda\\) 的真值表，用卡诺图或 HDL 综合成下一态与输出组合，接到寄存器 D 端。复位把状态送到已知编码。</p>',13)),(r(),s(n,null,{default:e(()=>[i(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20NS%5B%22%E4%B8%8B%E4%B8%80%E6%80%81%E7%BB%84%E5%90%88%22%5D%0A%20%20ST%5B%22%E7%8E%B0%E6%80%81%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20NS%0A%20%20NS%20--%3E%20ST%0A%20%20ST%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E7%BB%84%E5%90%88%22%5D%0A%20%20IN%20--%3E%20OUT%0A%20%20OUT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%AE%A1%E6%95%B0%E5%99%A8%E7%89%B9%E4%BE%8B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"独热编码让输出常是单触发器，下一态逻辑简单，FF 用得多。二进制编码省 FF，译码更重。后课控制真值表可以是「指令 × 状态」的大 ROM，仍是本课 FSM 的实现。非法状态应导向复位或陷阱，与无关项政策一致。",-1)),(r(),s(n,null,{default:e(()=>[i(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%204%20%E7%8A%B6%E6%80%81%E5%9B%BE%22%5D%20--%3E%20OH%5B%22%E7%8B%AC%E7%83%AD%EF%BC%9A%E6%AF%8F%E7%8A%B6%E6%80%81%201%20%E4%B8%AA%20FF%EF%BC%8C%E5%85%B1%204%20%E4%B8%AA%22%5D%0A%20%20ST%20--%3E%20BIN%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%EF%BC%9Aceil(log2%204)%20%3D%202%20%E4%B8%AA%20FF%22%5D%0A%20%20OH%20--%3E%20OH2%5B%22%E4%B8%8B%E4%B8%80%E6%80%81%E4%B8%8E%E8%BE%93%E5%87%BA%E9%80%BB%E8%BE%91%E7%AE%80%E5%8D%95%E3%80%81%E5%BF%AB%22%5D%0A%20%20BIN%20--%3E%20BIN2%5B%22%E7%9C%81%E8%A7%A6%E5%8F%91%E5%99%A8%EF%BC%8C%E8%AF%91%E7%A0%81%E7%BB%84%E5%90%88%E6%9B%B4%E9%87%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">这张图回答「同一状态图，编码换来换去换的是什么」：状态图不变，电路的面积与速度在变。初学者容易以为编码随便挑——综合后的时序和资源占用都随编码改变，独热多花触发器买「逻辑浅」，二进制省触发器但译码深。</span></p><p><span class="marginnote">非法状态是常见盲区：独热编码合法状态只有 4 个，可 4 个 FF 理论上有 16 种组合，其余 12 种都是非法态。若没有把非法态导向复位的逻辑，一个宇宙射线或竞态就可能让机器掉进死态回不来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证正则语言等价、不把下推自动机请进来。不讨论状态最小化算法细节。连续控制、PID 不是 FSM。</p><p>后课默认：控制器是同步 FSM；现态在寄存器，转移每拍一次。计数器是状态沿环走的特例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FSM = 状态寄存器 + 下一态/输出组合。</li><li>Moore/Mealy 差在输出是否看输入。</li><li>编码在独热与二进制之间权衡。</li><li>出处：Harris and Harris。</li></ul>',7))])}const D=B(A,[["render",m]]);export{u as __pageData,D as default};
